import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String s1 = br.readLine();String s2 = br.readLine();int target = 0;for (char c : s1.toCharArray()) {if (c == '+') target++;else target--;}int current = 0;int qCount = 0;for (char c : s2.toCharArray()) {if (c == '+') current++;else if (c == '-') current--;else qCount++;}int totalWays = 1 << qCount;int successWays = 0;for (int i = 0; i < totalWays; i++) {int tempPos = current;int tempI = i;for (int j = 0; j < qCount; j++) {if ((tempI & 1) == 1) tempPos++;else tempPos--;tempI >>= 1;}if (tempPos == target) successWays++;}System.out.printf("%.12f", (double) successWays / totalWays);}}